import sys
from collections import Counter

def is_palindrome(s):
    return s == s[::-1]

def generate_substrings(s):
    n = len(s)
    for i in range(n):
        for j in range(i + 1, n + 1):
            yield s[i:j]

def max_palindromic_count_string(s):
    n = len(s)
    char_count = Counter(s)

    # Create a list of characters sorted by their frequency
    chars = sorted(char_count.keys(), key=lambda x: (-char_count[x], x))

    # Construct the result string
    result = []
    odd_char = None

    for char in chars:
        count = char_count[char]
        if count % 2 == 1:
            if odd_char is None:
                odd_char = char
            else:
                result.append(char * (count - 1))
        else:
            result.append(char * count)

    if odd_char:
        result.insert(len(result) // 2, odd_char)

    return ''.join(result)

